  `refreshed_products` int unsigned NOT NULL DEFAULT '0',
  `skipped_fresh_products` int unsigned NOT NULL DEFAULT '0',
  `total_sites` int unsigned NOT NULL DEFAULT '0',
  `processed_sites` int unsigned NOT NULL DEFAULT '0',
  `quotes_written` int unsigned NOT NULL DEFAULT '0',
  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  `error_message` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_price_research_runs_uuid` (`uuid`),
  KEY `idx_price_research_runs_status_created` (`status`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=42 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
